fragment pr on PullRequest{number,title,state,headRefName,isDraft,url,updatedAt,author{login,...on User{id,name}},headRefOid,mergedAt}
		query PullRequestSearch(
			$q: String!,
			$type: SearchType!,
			$limit: Int!,
			$endCursor: String,
		) {
			search(query: $q, type: $type, first: $limit, after: $endCursor) {
				issueCount
				nodes {
					...pr
				}
				pageInfo {
					hasNextPage
					endCursor
				}
			}
		}

